$script:passed = 0
function Pass { param([string]$Name) $script:passed++; Write-Host "PASS $script:passed`: $Name" }
function Assert-True { param([bool]$Value,[string]$Name) if(-not $Value){throw "ASSERT TRUE: $Name"};Pass $Name }
function Assert-Equal { param($Actual,$Expected,[string]$Name) Assert-True ((@($Actual)-join '|') -ceq (@($Expected)-join '|')) $Name }
function Assert-Throws { param([scriptblock]$Action,[string]$Name) try {& $Action;throw 'expected throw'}catch{if($_.Exception.Message -eq 'expected throw'){throw};Pass $Name} }
function New-State {
 param([string]$Phase='routing',[string]$Status='needs_input')
 [pscustomobject][ordered]@{version=1;dispatchId='11111111-1111-1111-1111-111111111111';revision=[int64]5;createdAtUtc='2026-01-01T00:00:00.0000000Z';updatedAtUtc='2026-01-01T00:00:00.0000000Z';phase=$Phase;status=$Status;task='fix README typo';projectRepository=$null;threadId=$null;report='old report';question='Which project?';context='prior context';options=[string[]]@('owner/oss','owner/private');diagnostic=''}
}
function Copy-State { param($State) $copy=[ordered]@{};foreach($name in $State.PSObject.Properties.Name){$copy[$name]=if($name -eq 'options'){[string[]]@($State.options)}else{$State.$name}};[pscustomobject]$copy }
function Fast-Result { param([string]$Status='strong',$Repository='owner/oss') [pscustomobject][ordered]@{version=1;status=$Status;topScore=1;lead=1;selectedProject=$(if($Status -eq 'strong'){[pscustomobject][ordered]@{name='x';localPath='C:\router-local-path';githubRepository=$Repository;score=1;matchedSignals=,([object[]]@())}}else{$null});candidates=,([object[]]@())} }
function Slow-Result { param([string]$Status='routed') [pscustomobject][ordered]@{version=1;status=$Status;selectedProject=$(if($Status -eq 'routed'){[pscustomobject][ordered]@{name='x';localPath='C:\router-local-path';githubRepository='owner/private'}}else{$null});confidence='';reason=$(if($Status -eq 'no_match'){'MODEL-REASON'}else{''});question=$(if($Status -eq 'needs_input'){'MODEL-QUESTION'}else{''});options=$(if($Status -eq 'needs_input'){[string[]]@('owner/oss','owner/private')}else{,([string[]]@())})} }
function Worker-Result { param([string]$Status='completed',$Thread='22222222-2222-2222-2222-222222222222') [pscustomobject][ordered]@{version=1;status=$Status;project=[pscustomobject]@{name='untrusted';localPath='C:\worker-ignored';githubRepository='owner/ignored'};threadId=$Thread;report=$(if($Status -eq 'completed'){'completed report'}elseif($Status -eq 'needs_input'){'worker report'}else{''});question=$(if($Status -eq 'needs_input'){'worker question'}else{''});context=$(if($Status -eq 'needs_input'){'worker context'}else{''});options=$(if($Status -eq 'needs_input'){[string[]]@('A','B')}else{,([string[]]@())});exitCode=$(if($Status -eq 'failed'){1}else{0});diagnostic=$(if($Status -eq 'failed'){'RAW-WORKER-FAILURE C:\private'}else{''})} }
function New-Fixture {
 param($State,[string]$FastMode='strong',$FastRepository='owner/oss',[string]$SlowMode='routed',[string]$WorkerMode='completed',[string]$PublisherMode='updated')
 $ctx=[pscustomobject]@{State=$State;FastMode=$FastMode;FastRepository=$FastRepository;SlowMode=$SlowMode;WorkerMode=$WorkerMode;PublisherMode=$PublisherMode;Events=[Collections.Generic.List[string]]::new();Updates=0;Gets=0;FailUpdateAt=0;FailGetAt=0;FastRequest=$null;SlowRequest=$null;WorkerRequest=$null;PublisherRequest=$null;FastEnv=$null;SlowEnv=$null;WorkerEnv=$null;PublisherEnv=$null;RunningState=$null}
 $fastValue=if($FastMode -notin @('throw','malformed')){Fast-Result $FastMode $FastRepository}else{$null}
 $slowValue=if($SlowMode -notin @('throw','malformed')){Slow-Result $SlowMode}else{$null}
 $workerValue=if($WorkerMode -eq 'failednull'){Worker-Result failed $null}elseif($WorkerMode -eq 'failedinvalid'){Worker-Result failed bad}elseif($WorkerMode -notin @('throw','malformed')){Worker-Result $WorkerMode}else{$null}
 $get={param($request)[void]$ctx.Events.Add('Get');$ctx.Gets++;if($ctx.FailGetAt -eq $ctx.Gets){throw 'RAW-STATE-READ C:\private'};return $ctx.State}.GetNewClosure()
 $update={param($request)[void]$ctx.Events.Add('Update');$ctx.Updates++;if($ctx.FailUpdateAt -eq $ctx.Updates){throw 'RAW-STATE-WRITE C:\private'};if([int64]$request.ExpectedRevision -ne [int64]$ctx.State.revision){throw 'revision mismatch'};$values=[ordered]@{};foreach($name in $ctx.State.PSObject.Properties.Name){$values[$name]=if($name -eq 'options'){[string[]]@($ctx.State.options)}else{$ctx.State.$name}};$next=[pscustomobject]$values;$next.revision=[int64]$ctx.State.revision+1;$next.phase=[string]$request.Phase;$next.status=[string]$request.Status;foreach($pair in @(@('ProjectRepository','projectRepository'),@('ThreadId','threadId'),@('Report','report'),@('Question','question'),@('Context','context'),@('Options','options'),@('Diagnostic','diagnostic'))){if($request.Contains($pair[0])){if($pair[0] -eq 'Options'){$optionValues=[string[]]@($request[$pair[0]]);$next.options=$optionValues}else{$next.($pair[1])=$request[$pair[0]]}}};$ctx.State=$next;return $ctx.State}.GetNewClosure()
 $fast={param($request)[void]$ctx.Events.Add('Fast');$ctx.FastRequest=$request;$ctx.FastEnv=[Environment]::GetEnvironmentVariables([EnvironmentVariableTarget]::Process);if($ctx.FastMode -eq 'throw'){throw 'RAW-FAST C:\private'};if($ctx.FastMode -eq 'malformed'){return [pscustomobject]@{status='bad'}};return $fastValue}.GetNewClosure()
 $slow={param($request)[void]$ctx.Events.Add('Slow');$ctx.SlowRequest=$request;$ctx.SlowEnv=[Environment]::GetEnvironmentVariables([EnvironmentVariableTarget]::Process);if($ctx.SlowMode -eq 'throw'){throw 'RAW-SLOW C:\private'};if($ctx.SlowMode -eq 'malformed'){return [pscustomobject]@{status='bad'}};return $slowValue}.GetNewClosure()
 $worker={param($request)[void]$ctx.Events.Add('Worker');$ctx.WorkerRequest=$request;$ctx.WorkerEnv=[Environment]::GetEnvironmentVariables([EnvironmentVariableTarget]::Process);$ctx.RunningState=$ctx.State;if($ctx.WorkerMode -eq 'throw'){throw 'RAW-WORKER C:\private'};if($ctx.WorkerMode -eq 'malformed'){return [pscustomobject]@{status='bad'}};return $workerValue}.GetNewClosure()
 $publisher={param($request)[void]$ctx.Events.Add('Publisher');$ctx.PublisherRequest=$request;$ctx.PublisherEnv=[Environment]::GetEnvironmentVariables([EnvironmentVariableTarget]::Process);if($ctx.PublisherMode -eq 'throw'){throw 'RAW-PUBLISHER C:\private'};$action=$ctx.PublisherMode;$id=[string]$ctx.State.dispatchId;$revision=[int64]$ctx.State.revision;$number=[int64]$request.IssueNumber;if($action -eq 'wrongdispatch'){$action='updated';$id='33333333-3333-3333-3333-333333333333'}elseif($action -eq 'wrongrevision'){$action='updated';$revision++}elseif($action -eq 'wrongissue'){$action='updated';$number++};if($action -eq 'malformed'){return [pscustomobject]@{action='updated'}};return [pscustomobject][ordered]@{version=1;action=$action;dispatchId=$id;revision=$revision;repository='owner/control';issueNumber=$number;issueUrl='https://example.test/42'}}.GetNewClosure()
 return [pscustomobject]@{Dependencies=[pscustomobject][ordered]@{GetState=$get;UpdateState=$update;FastRouter=$fast;SlowRouter=$slow;Worker=$worker;Publisher=$publisher};Context=$ctx}
}
function Invoke-Fake { param($Fixture,[string]$Answer='owner/oss') Invoke-CodexDispatchRoutingResumeOrchestratorInternal -DispatchId '11111111-1111-1111-1111-111111111111' -Answer $Answer -IssueNumber 42 -ConfigPath '' -Dependencies $Fixture.Dependencies }
function Assert-NoCredential {param($Environment,[string]$Name)foreach($variable in @('CODEX_DISPATCH_GITHUB_TOKEN','GH_TOKEN','GITHUB_TOKEN')){Assert-True (-not $Environment.Contains($variable)) "$Name hides $variable"}}

$caseRoot=Join-Path ([IO.Path]::GetTempPath()) ('routing-resume-test-'+[guid]::NewGuid().ToString('N'));[void](New-Item -ItemType Directory $caseRoot);[IO.File]::WriteAllText((Join-Path $caseRoot 'project-index.json'),'{}',[Text.UTF8Encoding]::new($false));$saved=Get-CodexDispatchOrchestratorCredentialSnapshot
