 foreach($mode in @('strong-null','ambiguous','no_match','disabled')){$fast=if($mode -eq 'strong-null'){'strong'}else{$mode};$repo=if($mode -eq 'strong-null'){$null}else{'owner/oss'};$f=New-Fixture (New-State) -FastMode $fast -FastRepository $repo;$out=Invoke-Fake $f;Assert-True ($f.Context.Events -contains 'Slow') "Fast $mode invokes Slow"}
 foreach($mode in @('throw','malformed')){$f=New-Fixture (New-State) -FastMode $mode;$out=Invoke-Fake $f;Assert-Equal $out.phase routing "Fast $mode routing";Assert-Equal $out.status needs_input "Fast $mode needs input";Assert-True (-not ($f.Context.Events -contains 'Slow')) "Fast $mode no Slow";Assert-Equal $out.context 'A Router component failed or returned an invalid contract.' "Fast $mode fixed context"}
 foreach($mode in @('needs_input','no_match','disabled','throw','malformed')){$f=New-Fixture (New-State) -FastMode ambiguous -SlowMode $mode;$out=Invoke-Fake $f;Assert-Equal $out.phase routing "Slow $mode routing";Assert-Equal $out.status needs_input "Slow $mode needs input";Assert-True (-not ($f.Context.Events -contains 'Worker')) "Slow $mode no Worker"}
 $f=New-Fixture (New-State) -FastMode ambiguous -SlowMode needs_input;$out=Invoke-Fake $f;Assert-Equal $out.report 'Routing still needs a project selection.' 'Slow fixed report';Assert-Equal $out.question 'Which project did you mean?' 'Slow fixed question';Assert-Equal $out.context 'Slow Router still found multiple plausible projects.' 'Slow fixed context';Assert-Equal $out.options @('owner/oss','owner/private') 'Slow validated options';Assert-True (-not ((ConvertTo-Json $out -Depth 8).Contains('MODEL-QUESTION'))) 'Slow model text not persisted'
 foreach($mode in @('completed','needs_input','failed','failednull','failedinvalid','throw','malformed')){$f=New-Fixture (New-State) -WorkerMode $mode;$out=Invoke-Fake $f;if($mode -eq 'completed'){Assert-Equal $f.Context.State.status completed 'completed State';Assert-Equal $f.Context.State.threadId '22222222-2222-2222-2222-222222222222' 'completed thread'}elseif($mode -eq 'needs_input'){Assert-Equal $f.Context.State.status needs_input 'needs input State';Assert-Equal $f.Context.State.threadId '22222222-2222-2222-2222-222222222222' 'needs input thread';Assert-Equal $f.Context.State.options @('A','B') 'needs input shape'}else{Assert-Equal $f.Context.State.status failed "Worker $mode failed";if($mode -in @('failednull','failedinvalid','throw','malformed')){Assert-Equal $f.Context.State.threadId $null "Worker $mode null thread"}}}
 foreach($failure in @(@('FailUpdateAt',1,'first write'),@('FailGetAt',2,'routing readback'),@('FailUpdateAt',2,'worker write'),@('FailGetAt',3,'worker readback'),@('FailUpdateAt',3,'final write'),@('FailGetAt',4,'final readback'))){$f=New-Fixture (New-State);$f.Context.($failure[0])=$failure[1];Assert-Throws {Invoke-Fake $f} "State failure $($failure[2])";if($failure[1] -le 1 -or $failure[2] -eq 'routing readback'){Assert-True (-not ($f.Context.Events -contains 'Fast')) "fail stop before Router $($failure[2])"};if($failure[1] -le 2 -or $failure[2] -eq 'worker readback'){Assert-True (-not ($f.Context.Events -contains 'Worker')) "fail stop before Worker $($failure[2])"};Assert-True (-not ($f.Context.Events -contains 'Publisher')) "fail stop no Publisher $($failure[2])"}
 foreach($mode in @('updated','noop','created','wrongdispatch','wrongrevision','wrongissue','malformed','throw')){$f=New-Fixture (New-State) -PublisherMode $mode;$out=Invoke-Fake $f;if($mode -in @('updated','noop')){Assert-Equal $out.issuePublication $mode "Publisher $mode success"}else{Assert-Equal $out.issuePublication failed "Publisher $mode failed";Assert-Equal $out.issueNumber $null "Publisher $mode null number";Assert-Equal $out.issueUrl $null "Publisher $mode null url";Assert-Equal $out.projectionDiagnostic 'Issue publication failed.' "Publisher $mode fixed diagnostic"};Assert-Equal $f.Context.State.status completed "Publisher $mode preserves State"}
 $before=Get-CodexDispatchOrchestratorCredentialSnapshot;[Environment]::SetEnvironmentVariable('CODEX_DISPATCH_GITHUB_TOKEN','DEDICATED',[EnvironmentVariableTarget]::Process);Set-CodexDispatchOrchestratorEmptyEnvironmentVariable -Name 'GH_TOKEN';[Environment]::SetEnvironmentVariable('GITHUB_TOKEN','GENERAL',[EnvironmentVariableTarget]::Process);$expected=Get-CodexDispatchOrchestratorCredentialSnapshot;try{foreach($mode in @('success','fast','slow','worker','publisher','state')){$f=New-Fixture (New-State);if($mode -eq 'fast'){$f.Context.FastMode='throw'}elseif($mode -eq 'slow'){$f.Context.FastMode='ambiguous';$f.Context.SlowMode='throw'}elseif($mode -eq 'worker'){$f.Context.WorkerMode='throw'}elseif($mode -eq 'publisher'){$f.Context.PublisherMode='throw'}elseif($mode -eq 'state'){$f.Context.FailUpdateAt=1};try{Invoke-Fake $f|Out-Null}catch{};foreach($environment in @($f.Context.FastEnv,$f.Context.SlowEnv,$f.Context.WorkerEnv)){if($null -ne $environment){Assert-NoCredential $environment "$mode dependency"}};if($null -ne $f.Context.PublisherEnv){Assert-Equal $f.Context.PublisherEnv['CODEX_DISPATCH_GITHUB_TOKEN'] 'DEDICATED' "$mode Publisher dedicated";Assert-True (-not $f.Context.PublisherEnv.Contains('GH_TOKEN')) "$mode Publisher GH absent";Assert-True (-not $f.Context.PublisherEnv.Contains('GITHUB_TOKEN')) "$mode Publisher GitHub absent"};$snapshot=Get-CodexDispatchOrchestratorCredentialSnapshot;foreach($record in $expected){$current=@($snapshot|Where-Object{$_.name -ceq $record.name})[0];Assert-Equal $current.exists $record.exists "$mode restore exists $($record.name)";Assert-Equal $current.value $record.value "$mode restore value $($record.name)"}}}finally{Restore-CodexDispatchOrchestratorCredentials -Snapshot $before}
 $tokens=$null;$errors=$null;$ast=[System.Management.Automation.Language.Parser]::ParseFile($publicPath,[ref]$tokens,[ref]$errors);Assert-Equal $errors.Count 0 'public parser';Assert-Equal @($ast.ParamBlock.Parameters|ForEach-Object{$_.Name.VariablePath.UserPath}) @('DispatchId','Answer','IssueNumber','ConfigPath') 'public surface';$text=[IO.File]::ReadAllText($publicPath);foreach($name in @('Task','ProjectRepository','ThreadId','IndexPath','Token')){Assert-True (-not $text.Contains($name)) "public omits $name"}
} finally { Pop-Location;Restore-CodexDispatchOrchestratorCredentials -Snapshot $saved;Remove-Item -LiteralPath $caseRoot -Recurse -Force -ErrorAction SilentlyContinue }
